void panMouse(DrawingSheetEditor &e,QEvent::Type type,QPointF local,Qt::MouseButton button,Qt::MouseButtons buttons){auto *v=e.canvas();const QPointF global=v->viewport()->mapToGlobal(local.toPoint());QMouseEvent event(type,local,global,button,buttons,Qt::NoModifier);QApplication::sendEvent(v->viewport(),&event);}
void panKeyEvent(DrawingSheetEditor &e,QEvent::Type type,int key,bool repeat=false){QKeyEvent event(type,key,Qt::NoModifier,QString(),repeat);QApplication::sendEvent(e.canvas(),&event);}
void drawingPanTests(){
 auto body=std::make_shared<Body>(makeBox(Frame3(),12,8,6));auto names=std::make_shared<ElementNames>(propagateNames(*body,makeHistory({},*body),{},"pan"));DrawingEditorModel model{{{QUuid::createUuid(),{}},{{1,body,names}}},{{1,"Corpo"}},{}};DrawingSheet s;s.drawing.model=model.snapshot.version;DrawingSheetEditor e(s,model);e.resize(1200,800);e.show();QApplication::processEvents();e.fitSheet();DrawingView v;v.kind=DrawingViewKind::ProjectedEdges;v.scale=4;ok(e.insertView(v,{v.id,"Vista pan",{130,110},{1}}));QApplication::processEvents();e.markSaved();auto *canvas=e.canvas();canvas->scale(8,8);canvas->centerOn(148,105);canvas->setFocus();QApplication::processEvents();const auto before=encoded(e);const auto curve=e.curves(v.id)[0].curve.get();const auto transform=canvas->transform();const auto start=QPointF(canvas->viewport()->rect().center());
 const auto gesture=[&](Qt::MouseButton button,QPointF delta){const auto paper=canvas->mapToScene(start.toPoint());panMouse(e,QEvent::MouseButtonPress,start,button,button);require(canvas->cursor().shape()==Qt::ClosedHandCursor,"cursore mano chiusa durante pan");panMouse(e,QEvent::MouseMove,start+delta,Qt::NoButton,button);const auto movement=QPointF(canvas->mapFromScene(paper))-start;require(QLineF(movement,delta).length()<1.5,"pan in pixel anche a zoom elevato");panMouse(e,QEvent::MouseButtonRelease,start+delta,button,Qt::NoButton);require(encoded(e)==before&&canvas->transform()==transform&&!e.isModified()&&e.curves(v.id)[0].curve.get()==curve,"pan non modifica documento, zoom, cache o stato modificato");};
 // Le coordinate assolute arrotondate conservano anche movimenti frazionari HiDPI.
 const auto fractional=canvas->mapToScene(start.toPoint());panMouse(e,QEvent::MouseButtonPress,start,Qt::MiddleButton,Qt::MiddleButton);for(int i=1;i<=20;++i)panMouse(e,QEvent::MouseMove,start+QPointF(.35*i,.25*i),Qt::NoButton,Qt::MiddleButton);require(QLineF(QPointF(canvas->mapFromScene(fractional))-start,QPointF(7,5)).length()<1.5,"pan HiDPI non perde frazioni di pixel");panMouse(e,QEvent::MouseButtonRelease,start+QPointF(7,5),Qt::MiddleButton,Qt::NoButton);
 selectCurve(e,v.id,0);const auto selection=canvas->scene()->selectedItems();canvas->setCursor(Qt::CrossCursor);gesture(Qt::MiddleButton,{87,53});require(canvas->cursor().shape()==Qt::CrossCursor&&canvas->scene()->selectedItems()==selection,"pan ripristina cursore e selezione");canvas->setCursor(Qt::ArrowCursor);
 const int key=canvas->property("drawingPanKey").toInt();QKeyEvent override(QEvent::ShortcutOverride,key,Qt::NoModifier);QApplication::sendEvent(canvas,&override);require(override.isAccepted(),"tasto pan precede scorciatoie del menu");panKeyEvent(e,QEvent::KeyPress,key);require(canvas->cursor().shape()==Qt::OpenHandCursor,"tasto pan mostra mano aperta");gesture(Qt::LeftButton,{-54,28});require(canvas->cursor().shape()==Qt::OpenHandCursor,"mano aperta fino al rilascio del tasto");panKeyEvent(e,QEvent::KeyRelease,key);require(canvas->cursor().shape()==Qt::ArrowCursor,"rilascio pan ripristina cursore");
 // Il rilascio anticipato del tasto non trasforma la gesture in un trascinamento della geometria.
 panKeyEvent(e,QEvent::KeyPress,key);panMouse(e,QEvent::MouseButtonPress,start,Qt::LeftButton,Qt::LeftButton);panKeyEvent(e,QEvent::KeyRelease,key);panMouse(e,QEvent::MouseMove,start+QPointF(30,15),Qt::NoButton,Qt::LeftButton);panMouse(e,QEvent::MouseButtonRelease,start+QPointF(30,15),Qt::LeftButton,Qt::NoButton);require(encoded(e)==before&&canvas->cursor().shape()==Qt::ArrowCursor,"rilascio anticipato non trascina viste");
 // Quote, taglio e ghost restano attivi senza consumare clic o punti.
 auto *quote=e.findChild<QAction *>("drawingSmartDimensionAction");quote->setChecked(true);gesture(Qt::MiddleButton,{24,-17});require(quote->isChecked()&&e.sheet().drawing.dimensions.empty(),"pan durante quotatura conserva strumento senza inserire riferimenti");quote->setChecked(false);
 ok(e.beginSectionLine(v.id,"A"));const auto first=canvas->mapFromScene(QPointF(154,110));panMouse(e,QEvent::MouseButtonPress,first,Qt::LeftButton,Qt::LeftButton);panMouse(e,QEvent::MouseButtonRelease,first,Qt::LeftButton,Qt::NoButton);gesture(Qt::MiddleButton,{-26,-12});require(e.hasSectionLine(),"pan conserva primo punto del taglio");const auto second=canvas->mapFromScene(QPointF(154,90));panMouse(e,QEvent::MouseButtonPress,second,Qt::LeftButton,Qt::LeftButton);panMouse(e,QEvent::MouseButtonRelease,second,Qt::LeftButton,Qt::NoButton);require(e.hasViewPlacement()&&!e.hasSectionLine(),"dopo pan il secondo punto completa il taglio");panKeyEvent(e,QEvent::KeyPress,Qt::Key_Escape);require(encoded(e)==before,"annullare sezione dopo pan conserva stato");
 DrawingView another=v;another.id=QUuid::createUuid();ok(e.beginViewPlacement(another,{another.id,"Anteprima",{30,30},{1}}));gesture(Qt::MiddleButton,{19,11});require(e.hasViewPlacement()&&e.sheet().drawing.views.size()==1,"pan non inserisce o annulla ghost");panKeyEvent(e,QEvent::KeyPress,Qt::Key_Escape);
 // La perdita del focus deve interrompere la navigazione e liberare il cursore.
 panKeyEvent(e,QEvent::KeyPress,key);panMouse(e,QEvent::MouseButtonPress,start,Qt::LeftButton,Qt::LeftButton);QFocusEvent focus(QEvent::FocusOut,Qt::OtherFocusReason);QApplication::sendEvent(canvas,&focus);const auto afterFocus=canvas->mapToScene(start.toPoint());panMouse(e,QEvent::MouseMove,start+QPointF(40,20),Qt::NoButton,Qt::LeftButton);require(canvas->mapToScene(start.toPoint())==afterFocus&&canvas->cursor().shape()==Qt::ArrowCursor,"focus perso interrompe pan e tasto tenuto");panMouse(e,QEvent::MouseButtonRelease,start,Qt::LeftButton,Qt::NoButton);
 // Doppio clic e rilascio perso sono ancora navigazione, mai un'apertura proprieta'.
 panMouse(e,QEvent::MouseButtonDblClick,start,Qt::MiddleButton,Qt::MiddleButton);require(canvas->cursor().shape()==Qt::ClosedHandCursor,"doppio clic centrale avvia pan");panMouse(e,QEvent::MouseButtonRelease,start,Qt::MiddleButton,Qt::NoButton);require(!e.findChild<QDialog *>("drawingViewDialog"),"doppio clic pan non apre proprieta'");
 panMouse(e,QEvent::MouseButtonPress,start,Qt::MiddleButton,Qt::MiddleButton);const auto missingRelease=canvas->mapToScene(start.toPoint());panMouse(e,QEvent::MouseMove,start+QPointF(45,22),Qt::NoButton,Qt::NoButton);require(canvas->mapToScene(start.toPoint())==missingRelease&&canvas->cursor().shape()==Qt::ArrowCursor,"rilascio perso interrompe pan senza cursore bloccato");
 e.setReadOnly(true);gesture(Qt::MiddleButton,{-14,13});panKeyEvent(e,QEvent::KeyPress,key);gesture(Qt::LeftButton,{11,-12});panKeyEvent(e,QEvent::KeyRelease,key);require(e.isReadOnly(),"pan disponibile nello storico senza checkout");e.setReadOnly(false);
 // I normali spostamenti continuano a funzionare dopo la navigazione.
 e.fitSheet();const auto from=QPointF(canvas->mapFromScene(QPointF(154,94))),to=from+QPointF(30,20);panMouse(e,QEvent::MouseButtonPress,from,Qt::LeftButton,Qt::LeftButton);panMouse(e,QEvent::MouseMove,to,Qt::NoButton,Qt::LeftButton);panMouse(e,QEvent::MouseButtonRelease,to,Qt::LeftButton,Qt::NoButton);QApplication::processEvents();require(e.sheet().views[0].position!=QPointF(130,110),"trascinamento vista conservato dopo pan");ok(e.undo());require(encoded(e)==before,"un solo Undo annulla lo spostamento, nessun pan nella storia");
 std::cout<<"PASS pan tavola: centrale/tasto 3D+sinistro, zoom alto, cursore/selezioni, quota/taglio/ghost, sola lettura, focus, Undo e cache invariati\n";
}
